// Debug overlay (non-DirectDraw renderers only): draws the player's logical room index as on-screen text ("Logical Room->%d") plus the current room's collision grid and wall-tile overlays. Dev visualization left in the retail binary.
void __stdcall DEBUG_DrawLogicalRoomOverlay() {
    int nX;
    int nY;
    eD2RendererMode eRendererMode_lcl = D2gfx::D2GFX::D2GFX_GetRendererMode();
    if (eRendererMode_lcl == RENDERED_DirectDraw) {
      return;
    }

    D2UnitStrc* pUnit = UNIT::Player::GetPlayerUnit_Net();
    eD2UnitType eUnitType = pUnit->eUnitType;
    if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
      nX = pUnit->pPath.pStaticPath->nPosX;
    } else if (pUnit->pPath.pDynamicPath) {
      nX = D2Common::PATH::DynamicPath::GetXPos(pUnit->pPath.pDynamicPath);
    } else {
      nX = 0;
    }

    eUnitType = pUnit->eUnitType;
    if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
      nY = pUnit->pPath.pStaticPath->nPosY;
    } else if (pUnit->pPath.pDynamicPath) {
      nY = D2Common::PATH::DynamicPath::GetYPos(pUnit->pPath.pDynamicPath);
    } else {
      nY = 0;
    }

    D2RoomStrc* pRoom = D2Common::Units::UNITS_GetRoom(pUnit);
    int32_t nGridIndex = D2Common::DUNGEON::Dungeon::GetGridIndex(pRoom, nX, nY);
    D2gfx::D2GFX::D2GFX_DrawString(10, 0x37, "Logical Room->%d", nGridIndex);
    DRAW_DrawRoomCollisionGrid(pRoom);
    DRAW_DrawRoomWallTiles(pRoom);
}

